#include "DomainGenerator.hpp"
#include "../Utils/FileWriter.hpp"
#include <filesystem>
namespace exotic { void DomainGenerator::Generate(const std::string& name){ std::string root="Domains/"+name; std::filesystem::create_directories(root); FileWriter::Write(root+"/README.md","# "+name+" Domain\n\nGenerated by Exotic Builder.\n\n## Domain Structure\n\n- Dashboard\n- Workspace\n- Assets\n- Projects\n- Automation\n- Intelligence\n- Analytics\n- Collaboration\n- Marketplace\n- Documentation\n- Settings\n- Developer\n\n## Rule\n\nEvery domain maps to customer value, security, tests, docs, and evolution.\n"); FileWriter::Write(root+"/"+name+"Domain.hpp","#pragma once\n#include ^<string^>\n\nnamespace exotic\n{\n\n//==========================================================\n// DOMAIN\n//==========================================================\n\nclass "+name+"Domain\n{\npublic:\n    void Initialize();\n    void RegisterModules();\n    void Shutdown();\n\nprivate:\n    std::string name = \""+name+"\";\n    bool active = false;\n};\n\n}\n"); FileWriter::Write(root+"/"+name+"Domain.cpp","#include \""+name+"Domain.hpp\"\n#include ^<iostream^>\n\nnamespace exotic\n{\n\nvoid "+name+"Domain::Initialize()\n{\n    active = true;\n    std::cout ^<^< \""+name+" domain initialized.\" ^<^< std::endl;\n}\n\nvoid "+name+"Domain::RegisterModules()\n{\n    if (!active) return;\n}\n\nvoid "+name+"Domain::Shutdown()\n{\n    active = false;\n}\n\n}\n"); std::filesystem::create_directories(root+"/Dashboard"); std::filesystem::create_directories(root+"/Workspace"); std::filesystem::create_directories(root+"/Assets"); std::filesystem::create_directories(root+"/Projects"); std::filesystem::create_directories(root+"/Automation"); std::filesystem::create_directories(root+"/Intelligence"); std::filesystem::create_directories(root+"/Analytics"); std::filesystem::create_directories(root+"/Collaboration"); std::filesystem::create_directories(root+"/Marketplace"); std::filesystem::create_directories(root+"/Documentation"); std::filesystem::create_directories(root+"/Settings"); std::filesystem::create_directories(root+"/Developer"); } }
